(function(){"use strict";var R=document.documentElement;if(R.getAttribute("data-visual")!=="novo")return;var PAL=[[116,162,240],[70,189,180],[234,179,84],[116,201,159],[182,144,234],[240,125,112],[151,163,182]];function perto(txt){var m=(txt||"").match(/\d+/g);if(!m||m.length<3)return null;var best=null,bd=1e9,cz=Math.abs(m[0]-m[1])<40&&Math.abs(m[1]-m[2])<40;PAL.forEach((function(p,i){if(cz&&i!==6)return;if(!cz&&i===6)return;var d=(p[0]-m[0])*(p[0]-m[0])+(p[1]-m[1])*(p[1]-m[1])+(p[2]-m[2])*(p[2]-m[2]);if(d<bd){bd=d;best=p}}));return best&&"rgb("+best.join(",")+")"}function ico(svg){var s=svg.outerHTML.replace(/currentColor/g,"#fff").replace(/ (width|height|style)="[^"]*"/g,"");if(s.indexOf("xmlns")<0)s=s.replace("<svg",'<svg xmlns="http://www.w3.org/2000/svg"');return'url("data:image/svg+xml,'+encodeURIComponent(s)+'")'}function aplicar(){var nav={};document.querySelectorAll(".sidebar .nav-item").forEach((function(a){nav[(a.getAttribute("title")||a.textContent).trim()]=a}));document.querySelectorAll(".mod-card").forEach((function(c){var h=c.querySelector("h3");if(!h)return;var a=nav[h.textContent.trim()];if(!a)return;if(c.getAttribute("data-palco")===a.getAttribute("href"))return;var sv=a.querySelector("svg");if(sv)c.style.setProperty("--ico",ico(sv));var k=getComputedStyle(a).getPropertyValue("--k").trim();if(k)c.style.setProperty("--k",k);c.setAttribute("data-palco",a.getAttribute("href"))}));document.querySelectorAll('div[style*="flex: 0 0 250px"]').forEach((function(col){var dot=col.firstElementChild&&col.firstElementChild.firstElementChild;if(!dot)return;var k=perto(dot.style.background||getComputedStyle(dot).backgroundColor);if(k&&col.style.getPropertyValue("--pk")!==k)col.style.setProperty("--pk",k)}))}var ag=false;function agenda(){if(ag)return;ag=true;requestAnimationFrame((function(){ag=false;aplicar()}))}aplicar();new MutationObserver(agenda).observe(document.body,{childList:true,subtree:true})})();